if update is big then please use batch update. Like this - 
{code:sql}
USE taxify_company;
DROP PROCEDURE if exists update_in_loop;

DELIMITER $$
CREATE PROCEDURE update_in_loop()
BEGIN
    SELECT MIN(id), MAX(id), 5000 INTO @min_id, @max_id, @batch_size FROM `taxify_company`.`order_try_route_log`;

    SELECT @min_id, @max_id;

    WHILE @min_id <= @max_id DO
            
      UPDATE `taxify_company`.`order_try_route_log`
      SET `stop_type` = 'change_point' WHERE id between @min_id AND @min_id + @batch_size AND `stop_type` = 'waypoint';

      SET @min_id = @min_id + @batch_size;
      SELECT @min_id;

    END WHILE;
END;
$$
DELIMITER ;

CALL update_in_loop();
DROP PROCEDURE if exists update_in_loop;
{code}

